export class Camera{constructor(w,h){this.w=w;this.h=h;this.x=0;this.y=0;this.worldWidth=2400;this.worldHeight=1600}follow(t){if(!t)return;this.x+=(t.x-this.w/2-this.x)*.1;this.y+=(t.y-this.h/2-this.y)*.1;this.x=Math.max(0,Math.min(this.x,this.worldWidth-this.w));this.y=Math.max(0,Math.min(this.y,this.worldHeight-this.h))}worldToScreen(x,y){return{x:x-this.x,y:y-this.y}}}
